function rangeUpdate(graph,c,values){const[start,end,lmin,lmax,rmin,rmax,tickInterval='auto']=values,u={},hasRight=(graph?.data||[]).some(t=>(t.yaxis||'y')==='y2');if(start&&end){u['xaxis.range']=[start,end];u['xaxis.autorange']=false;const dateAxis=smartDateAxis(start,end,graph?.clientWidth||window.innerWidth,false,tickInterval||'auto');for(const key of['tickformat','tickangle','nticks','automargin','dtick','tick0'])u[`xaxis.${key}`]=dateAxis[key]??null}else u['xaxis.autorange']=true;for(const[axis,lo,hi,side]of[['yaxis',lmin,lmax,'left'],['yaxis2',rmin,rmax,'right']]){if(axis==='yaxis2'&&!hasRight)continue;if(lo!==''&&hi!==''){u[`${axis}.range`]=[Number(lo),Number(hi)];u[`${axis}.autorange`]=false}else{const visible=visibleAxisRange(graph,axis==='yaxis'?'y':'y2',start,end,!!c.config?.[`${side}_axis`]?.reverse);if(visible){u[`${axis}.range`]=visible;u[`${axis}.autorange`]=false}else u[`${axis}.autorange`]=true}}return u}
async function applyFrameRange(frame,c,values){const graph=frameGraph(frame),lib=frame?.contentWindow?.Plotly;if(!graph||!lib)return false;await lib.relayout(graph,rangeUpdate(graph,c,values));return true}
async function previewFrameRange(c,frame,values){const ok=await applyFrameRange(frame,c,values);if(ok)showMessage('范围预览已更新；点击“应用范围”后才会保存并留痕。');return ok}
function lastValueAnnotations(graph){const range=graph?.layout?.xaxis?.range||[],start=range[0],end=range[1],numericRange=Number.isFinite(Number(start))&&Number.isFinite(Number(end)),out=[];(graph?.data||[]).forEach((trace,traceIndex)=>{if(trace.visible==='legendonly'||trace.showlegend===false||trace.fill==='tonexty')return;let hit=null;(trace.y||[]).forEach((value,i)=>{const x=(trace.x||[])[i],number=Number(value),visible=numericRange?Number(x)>=Number(start)&&Number(x)<=Number(end):(!start||String(x)>=String(start))&&(!end||String(x)<=String(end));if(Number.isFinite(number)&&visible)hit={x,y:number}});if(!hit)return;const color=trace.line?.color||trace.marker?.color||'#17212b';out.push({x:hit.x,y:hit.y,xref:'x',yref:(trace.yaxis||'y')==='y2'?'y2':'y',text:fmt(hit.y),showarrow:false,xanchor:'right',yanchor:'middle',xshift:-7,yshift:(traceIndex%3-1)*15,font:{size:12,color},bgcolor:'rgba(255,255,255,.88)',bordercolor:'rgba(255,255,255,0)',borderpad:2})});return out}
async function exportFrame(frame,filename,labelLast=false){const graph=frameGraph(frame),lib=frame?.contentWindow?.Plotly;if(!graph||!lib)return false;const original=Array.isArray(graph.layout?.annotations)?graph.layout.annotations:[];try{if(labelLast)await lib.relayout(graph,{annotations:[...original,...lastValueAnnotations(graph)]});const dataUrl=await lib.toImage(graph,{format:'png',width:1550,height:700,scale:2});const link=document.createElement('a');link.href=dataUrl;link.download=`${filename}.png`;document.body.appendChild(link);link.click();link.remove();return true}catch(error){console.error('PNG export failed',error);return false}finally{if(labelLast)await lib.relayout(graph,{annotations:original})}}
function rangeValue(value){return value===''||value==null?null:Number(value)}
function rangeConfig(c,values){const[start,end,lmin,lmax,rmin,rmax,tickInterval='auto']=values,cfg=JSON.parse(JSON.stringify(c.config||{}));cfg.chart_id=c.chart_id;cfg.title=c.title;cfg.domain=c.domain;cfg.status=c.status;cfg.access_level=c.access_level;cfg.base_start_date=start||cfg.start_date;cfg.base_end_date=end||cfg.end_date;cfg.start_date=start||cfg.start_date;cfg.end_date=end||cfg.end_date;cfg.end_mode='fixed';cfg.date_tick_interval=tickInterval||'auto';cfg.left_axis={...(cfg.left_axis||{}),min:rangeValue(lmin),max:rangeValue(lmax)};cfg.right_axis={...(cfg.right_axis||{}),min:rangeValue(rmin),max:rangeValue(rmax)};cfg._change_reason='chart_range_update';return cfg}
