async function saveFrameRange(c,frame,values,source='range'){if(!await applyFrameRange(frame,c,values))throw new Error('图表仍在加载，请稍后再应用。');const cfg=rangeConfig(c,values),graph=frameGraph(frame);if(STATIC_MODE)cfg.preview_figure=portableFigure(graph);const result=await getJSON('/api/charts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(cfg)});c.config=rangeConfig(c,values);delete c.config._change_reason;await reloadCharts();const fresh=state.charts.find(x=>x.chart_id===c.chart_id);if(source==='viewer'&&frame?.isConnected&&fresh){frame.removeAttribute('srcdoc');frame.src='about:blank';frame.onload=()=>requestAnimationFrame(()=>{const g=frameGraph(frame),lib=frame.contentWindow?.Plotly;if(g&&lib)lib.Plots.resize(g)});requestAnimationFrame(()=>{if(fresh.html_url)frame.src=fresh.html_url+(fresh.html_url.includes('?')?'&':'?')+`embed=1&viewer=1&v=${Date.now()}`;else if(fresh.figure)frame.srcdoc=localFigureDocument(fresh,true);else frame.src=fresh.png_url||''})}showMessage(`已保存新默认范围并留存版本 V${String(result.version||1).padStart(3,'0')}。`);return result}
function fillViewerControls(c){const cfg=c.config||{},left=cfg.left_axis||{},right=cfg.right_axis||{};$('viewerStart').value=cfg.start_date||'';$('viewerEnd').value=cfg.end_date||'';$('viewerLeftMin').value=left.min??'';$('viewerLeftMax').value=left.max??'';$('viewerRightMin').value=right.min??'';$('viewerRightMax').value=right.max??'';$('viewerDateTick').value=cfg.date_tick_interval||'auto';$('viewerLabelLast').checked=false}
function openViewer(chartId,origin){const c=state.charts.find(x=>x.chart_id===chartId);if(!c)return;state.viewerOrigin=origin||'gallery';state.viewerChartId=chartId;$('viewerTitle').textContent=c.title;$('viewerMeta').textContent=`${c.chart_id} · ${kindLabel(chartKind(c))} · ${c.domain||'未分类'}`;fillViewerControls(c);const frame=$('viewerFrame');frame.removeAttribute('srcdoc');frame.src='about:blank';$('viewerExport').href='#';$('viewerExport').download=`${c.chart_id}.png`;$('viewerExport').style.display='inline-flex';$('chartViewer').showModal();frame.onload=()=>{requestAnimationFrame(()=>{const g=frameGraph(frame),lib=frame.contentWindow?.Plotly;if(g&&lib)lib.Plots.resize(g)})};requestAnimationFrame(()=>{if(c.html_url)frame.src=c.html_url+(c.html_url.includes('?')?'&':'?')+'embed=1&viewer=1';else if(c.figure)frame.srcdoc=localFigureDocument(c,true);else frame.src=c.png_url||''})}
