function selectedShowcaseCharts(){const q=$('showcaseSearch')?.value.trim().toLowerCase()||'',k=$('showcaseKind')?.value||'',d=$('showcaseDomain')?.value||'';return state.charts.filter(c=>state.showcase.has(c.chart_id)&&(!k||chartKind(c)===k)&&(!d||c.domain===d)&&(!q||[c.title,c.chart_id,c.domain,JSON.stringify(c.config||{})].join(' ').toLowerCase().includes(q)))}
