  $('saveChart').onclick=async()=>{if(!state.series.length)return showMessage('请先选择指标。',true);try{const config=chartConfig();if(!config.chart_id&&chartKind({config})==='dual'){const matches=state.charts.filter(c=>chartKind(c)==='dual'&&sameIndicatorCombo(c.config,config));if(matches.length){const choice=await duplicateDecision(matches);if(choice.action==='cancel')return;if(choice.action==='update'){config.chart_id=choice.chart.chart_id;state.chartId=choice.chart.chart_id}}}if(STATIC_MODE){config.preview_data_url=await Plotly.toImage($('chart'),{format:'png',width:1550,height:700});config.preview_figure={data:$('chart').data,layout:$('chart').layout}}const r=await getJSON('/api/charts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(config)});state.chartId=r.chart_id;await reloadCharts();showMessage(r.preview_mode?`已加入离线图库：${r.chart_id}。`:`已加入图库：${r.chart_id}，图库已同步。`);switchView('gallery')}catch(e){showMessage(e.message,true)}};
